INSERT INTO anime (id, title, cover_image, banner_image, description, average_score, popularity, episodes, status, format)
VALUES
    (16498, '{"romaji":"Shingeki no Kyojin","english":"Attack on Titan","native":"進撃の巨人","userPreferred":"Shingeki no Kyojin"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx16498-buvcRTBx4NSm.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx16498-buvcRTBx4NSm.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/16498-8jpFCOcDmneX.jpg', 'Several hundred years ago, humans were nearly exterminated by titans. Titans are typically several stories tall, seem to have no intelligence, devour human beings and, worst of all, seem to do it for the pleasure rather than as a food source. A small percentage of humanity survived by walling themselves in a city protected by extremely high walls, even taller than the biggest of titans. Flash forward to the present and the city has not seen a titan in over 100 years. Teenage boy Eren and his foster sister Mikasa witness something horrific as the city walls are destroyed by a colossal titan that appears out of thin air. As the smaller titans flood the city, the two kids watch in horror as their mother is eaten alive. Eren vows that he will murder every single titan and take revenge for all of mankind. (Source: MangaHelpers)', 85, 1078245, 25, 'FINISHED', 'TV'),
    (101922, '{"romaji":"Kimetsu no Yaiba","english":"Demon Slayer: Kimetsu no Yaiba","native":"鬼滅の刃","userPreferred":"Kimetsu no Yaiba"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx101922-WBsBl0ClmgYL.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101922-WBsBl0ClmgYL.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101922-33MtJGsUSxga.jpg', 'It is the Taisho Period in Japan. Tanjiro, a kindhearted boy who sells charcoal for a living, finds his family slaughtered by a demon. To make matters worse, his younger sister Nezuko, the sole survivor, has been transformed into a demon herself. Though devastated by this grim reality, Tanjiro resolves to become a “demon slayer” so that he can turn his sister back into a human, and kill the demon that massacred his family. (Source: Crunchyroll)', 82, 1014370, 26, 'FINISHED', 'TV'),
    (113415, '{"romaji":"Jujutsu Kaisen","english":"JUJUTSU KAISEN","native":"呪術廻戦","userPreferred":"Jujutsu Kaisen"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx113415-LHBAeoZDIsnF.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx113415-LHBAeoZDIsnF.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/113415-jQBSkxWAAk83.jpg', 'A boy fights... for "the right death." Hardship, regret, shame: the negative feelings that humans feel become Curses that lurk in our everyday lives. The Curses run rampant throughout the world, capable of leading people to terrible misfortune and even death. What''s more, the Curses can only be exorcised by another Curse. Itadori Yuji is a boy with tremendous physical strength, though he lives a completely ordinary high school life. One day, to save a friend who has been attacked by Curses, he eats the finger of the Double-Faced Specter, taking the Curse into his own soul. From then on, he shares one body with the Double-Faced Specter. Guided by the most powerful of sorcerers, Gojou Satoru, Itadori is admitted to the Tokyo Metropolitan Technical High School of Sorcery, an organization that fights the Curses... and thus begins the heroic tale of a boy who became a Curse to exorcise a Curse, a life from which he could never turn back. (Source: Crunchyroll) Note: The first episode received an early web premiere on September 19th, 2020. The regular TV broadcast started on October 3rd, 2020.', 84, 995944, 24, 'FINISHED', 'TV'),
    (1535, '{"romaji":"DEATH NOTE","english":"Death Note","native":"DEATH NOTE","userPreferred":"DEATH NOTE"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx1535-kUgkcrfOrkUM.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1535-kUgkcrfOrkUM.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1535.jpg', 'Light Yagami is a genius high school student who is about to learn about life through a book of death. When a bored shinigami, a God of Death, named Ryuk drops a black notepad called a Death Note , Light receives power over life and death with the stroke of a pen. Determined to use this dark gift for the best, Light sets out to rid the world of evil… namely, the people he believes to be evil. Should anyone hold such power? The consequences of Light’s actions will set the world ablaze. (Source: VIZ Media)', 84, 982599, 37, 'FINISHED', 'TV'),
    (21459, '{"romaji":"Boku no Hero Academia","english":"My Hero Academia","native":"僕のヒーローアカデミア","userPreferred":"Boku no Hero Academia"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21459-nYh85uj2Fuwr.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21459-nYh85uj2Fuwr.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21459-yeVkolGKdGUV.jpg', 'What would the world be like if 80 percent of the population manifested extraordinary superpowers called “Quirks” at age four? Heroes and villains would be battling it out everywhere! Becoming a hero would mean learning to use your power, but where would you go to study? U.A. High''s Hero Program of course! But what would you do if you were one of the 20 percent who were born Quirkless? Middle school student Izuku Midoriya wants to be a hero more than anything, but he hasn''t got an ounce of power in him. With no chance of ever getting into the prestigious U.A. High School for budding heroes, his life is looking more and more like a dead end. Then an encounter with All Might, the greatest hero of them all gives him a chance to change his destiny… (Source: VIZ Media)', 76, 890256, 13, 'FINISHED', 'TV'),
    (11061, '{"romaji":"HUNTER×HUNTER (2011)","english":"Hunter x Hunter (2011)","native":"HUNTER×HUNTER (2011)","userPreferred":"HUNTER×HUNTER (2011)"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx11061-y5gsT1hoHuHw.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11061-y5gsT1hoHuHw.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11061-8WkkTZ6duKpq.jpg', 'A Hunter is one who travels the world doing all sorts of dangerous tasks. From capturing criminals to searching deep within uncharted lands for any lost treasures. Gon is a young boy whose father disappeared long ago, being a Hunter. He believes if he could also follow his father''s path, he could one day reunite with him. After becoming 12, Gon leaves his home and takes on the task of entering the Hunter exam, notorious for its low success rate and high probability of death to become an official Hunter. He befriends the revenge-driven Kurapika, the doctor-to-be Leorio and the rebellious ex-assassin Killua in the exam, with their friendship prevailing throughout the many trials and threats they come upon taking on the dangerous career of a Hunter.', 89, 857559, 148, 'FINISHED', 'TV'),
    (21087, '{"romaji":"One Punch Man","english":"One-Punch Man","native":"ワンパンマン","userPreferred":"One Punch Man"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21087-B5DHjqZ3kW4b.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21087-B5DHjqZ3kW4b.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21087-sHb9zUZFsHe1.jpg', 'Saitama has a rather peculiar hobby, being a superhero, but despite his heroic deeds and superhuman abilities, a shadow looms over his life. He''s become much too powerful, to the point that every opponent ends up defeated with a single punch. The lack of challenge has driven him into a state of apathy, as he watches his life pass by having lost all enthusiasm, at least until he''s unwillingly thrust in the role of being a mentor to the young and revenge-driven Genos.', 82, 780348, 12, 'FINISHED', 'TV'),
    (21, '{"romaji":"ONE PIECE","english":"ONE PIECE","native":"ONE PIECE","userPreferred":"ONE PIECE"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21-ELSYx3yMPcKM.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21-ELSYx3yMPcKM.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21-wf37VakJmZqs.jpg', 'Gold Roger was known as the Pirate King, the strongest and most infamous being to have sailed the Grand Line. The capture and death of Roger by the World Government brought a change throughout the world. His last words before his death revealed the location of the greatest treasure in the world, One Piece. It was this revelation that brought about the Grand Age of Pirates, men who dreamed of finding One Piece (which promises an unlimited amount of riches and fame), and quite possibly the most coveted of titles for the person who found it, the title of the Pirate King. Enter Monkey D. Luffy, a 17-year-old boy that defies your standard definition of a pirate. Rather than the popular persona of a wicked, hardened, toothless pirate who ransacks villages for fun, Luffy’s reason for being a pirate is one of pure wonder; the thought of an exciting adventure and meeting new and intriguing people, along with finding One Piece, are his reasons of becoming a pirate. Following in the footsteps of his childhood hero, Luffy and his crew travel across the Grand Line, experiencing crazy adventures, unveiling dark mysteries and battling strong enemies, all in order to reach One Piece. *This include', 87, 769142, NULL, 'RELEASING', 'TV'),
    (20605, '{"romaji":"Tokyo Ghoul","english":"Tokyo Ghoul","native":"東京喰種 トーキョーグール","userPreferred":"Tokyo Ghoul"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b20605-k665mVkSug8D.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b20605-k665mVkSug8D.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20605-RCJ7M71zLmrh.jpg', 'The suspense horror/dark fantasy story is set in Tokyo, which is haunted by mysterious "ghouls" who are devouring humans. People are gripped by the fear of these ghouls whose identities are masked in mystery. An ordinary college student named Kaneki encounters Rize, a girl who is an avid reader like him, at the café he frequents. Little does he realize that his fate will change overnight. (Source: Anime News Network)', 76, 754505, 12, 'FINISHED', 'TV'),
    (20958, '{"romaji":"Shingeki no Kyojin Season 2","english":"Attack on Titan Season 2","native":"進撃の巨人 Season２","userPreferred":"Shingeki no Kyojin Season 2"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20958-HuFJyr54Mmir.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20958-HuFJyr54Mmir.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20958-Y7eQdz9VENBD.jpg', 'Eren Jaeger swore to wipe out every last Titan, but in a battle for his life he wound up becoming the thing he hates most. With his new powers, he fights for humanity''s freedom facing the monsters that threaten his home. After a bittersweet victory against the Female Titan, Eren finds no time to rest—a horde of Titans is approaching Wall Rose and the battle for humanity continues! (Source: Funimation)', 85, 748454, 12, 'FINISHED', 'TV'),
    (5114, '{"romaji":"Hagane no Renkinjutsushi: FULLMETAL ALCHEMIST","english":"Fullmetal Alchemist: Brotherhood","native":"鋼の錬金術師 FULLMETAL ALCHEMIST","userPreferred":"Hagane no Renkinjutsushi: FULLMETAL ALCHEMIST"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx5114-nSWCgQlmOMtj.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx5114-nSWCgQlmOMtj.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/5114-q0V5URebphSG.jpg', '"In order for something to be obtained, something of equal value must be lost." Alchemy is bound by this Law of Equivalent Exchange—something the young brothers Edward and Alphonse Elric only realize after attempting human transmutation: the one forbidden act of alchemy. They pay a terrible price for their transgression—Edward loses his left leg, Alphonse his physical body. It is only by the desperate sacrifice of Edward''s right arm that he is able to affix Alphonse''s soul to a suit of armor. Devastated and alone, it is the hope that they would both eventually return to their original bodies that gives Edward the inspiration to obtain metal limbs called "automail" and become a state alchemist, the Fullmetal Alchemist. Three years of searching later, the brothers seek the Philosopher''s Stone, a mythical relic that allows an alchemist to overcome the Law of Equivalent Exchange. Even with military allies Colonel Roy Mustang, Lieutenant Riza Hawkeye, and Lieutenant Colonel Maes Hughes on their side, the brothers find themselves caught up in a nationwide conspiracy that leads them not only to the true nature of the elusive Philosopher''s Stone, but their country''s murky history as well. ', 90, 743994, 64, 'FINISHED', 'TV'),
    (20, '{"romaji":"NARUTO","english":"Naruto","native":"NARUTO -ナルト-","userPreferred":"NARUTO"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20-dE6UHbFFg1A5.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20-dE6UHbFFg1A5.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20-HHxhPj5JD13a.jpg', 'Naruto Uzumaki, a hyperactive and knuckle-headed ninja, lives in Konohagakure, the Hidden Leaf village. Moments prior to his birth, a huge demon known as the Kyuubi, the Nine-tailed Fox, attacked Konohagakure and wreaked havoc. In order to put an end to the Kyuubi''s rampage, the leader of the village, the 4th Hokage, sacrificed his life and sealed the monstrous beast inside the newborn Naruto. Shunned because of the presence of the Kyuubi inside him, Naruto struggles to find his place in the village. He strives to become the Hokage of Konohagakure, and he meets many friends and foes along the way. (Source: MAL Rewrite)', 80, 741201, 220, 'FINISHED', 'TV'),
    (20954, '{"romaji":"Koe no Katachi","english":"A Silent Voice","native":"聲の形","userPreferred":"Koe no Katachi"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20954-sYRfE5jQRtSB.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20954-sYRfE5jQRtSB.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20954-f30bHMXa5Qoe.jpg', 'After transferring into a new school, a deaf girl, Shouko Nishimiya, is bullied by the popular Shouya Ishida. As Shouya continues to bully Shouko, the class turns its back on him. Shouko transfers and Shouya grows up as an outcast. Alone and depressed, the regretful Shouya finds Shouko to make amends. (Source: Eleven Arts)', 88, 732751, 1, 'FINISHED', 'MOVIE'),
    (11757, '{"romaji":"Sword Art Online","english":"Sword Art Online","native":"ソードアート・オンライン","userPreferred":"Sword Art Online"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx11757-SxYDUzdr9rh2.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11757-SxYDUzdr9rh2.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11757-TlEEV9weG4Ag.jpg', 'In the near future, a Virtual Reality Massive Multiplayer Online Role-Playing Game (VRMMORPG) called Sword Art Online has been released where players control their avatars with their bodies using a piece of technology called Nerve Gear. One day, players discover they cannot log out, as the game creator is holding them captive unless they reach the 100th floor of the game''s tower and defeat the final boss. However, if they die in the game, they die in real life. Their struggle for survival starts now... (Source: Crunchyroll)', 70, 732707, 25, 'FINISHED', 'TV'),
    (21519, '{"romaji":"Kimi no Na wa.","english":"Your Name.","native":"君の名は。","userPreferred":"Kimi no Na wa."}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21519-SUo3ZQuCbYhJ.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21519-SUo3ZQuCbYhJ.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21519-1ayMXgNlmByb.jpg', 'Mitsuha Miyamizu, a high school girl, yearns to live the life of a boy in the bustling city of Tokyo—a dream that stands in stark contrast to her present life in the countryside. Meanwhile in the city, Taki Tachibana lives a busy life as a high school student while juggling his part-time job and hopes for a future in architecture. One day, Mitsuha awakens in a room that is not her own and suddenly finds herself living the dream life in Tokyo—but in Taki''s body! Elsewhere, Taki finds himself living Mitsuha''s life in the humble countryside. In pursuit of an answer to this strange phenomenon, they begin to search for one another. Kimi no Na wa. revolves around Mitsuha and Taki''s actions, which begin to have a dramatic impact on each other''s lives, weaving them into a fabric held together by fate and circumstance. (Source: MAL Rewrite)', 85, 728676, 1, 'FINISHED', 'MOVIE'),
    (99147, '{"romaji":"Shingeki no Kyojin Season 3","english":"Attack on Titan Season 3","native":"進撃の巨人 Season３","userPreferred":"Shingeki no Kyojin Season 3"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx99147-AiPDD8cwlCfi.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99147-AiPDD8cwlCfi.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99147-HACsFVrynFf5.jpg', 'Eren and his companions in the 104th are assigned to the newly-formed Levi Squad, whose assignment is to keep Eren and Historia safe given Eren''s newly-discovered power and Historia''s knowledge and pedigree. Levi and Erwin have good reason to be concerned, because the priest of the Church that Hanji had hidden away was found tortured to death, making it clear that the Military Police are involved with the cover-up. Things get more harrowing when the MPs make a move on Erwin and the Levi Squad narrowly avoids capture. Eren is also having problems with his Titan transformation, and a deadly killer has been hired to secure Eren and Historia, one Levi knows all too well from his youth. (Source: Anime News Network)', 86, 700544, 12, 'FINISHED', 'TV'),
    (21856, '{"romaji":"Boku no Hero Academia 2","english":"My Hero Academia Season 2","native":"僕のヒーローアカデミア２","userPreferred":"Boku no Hero Academia 2"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21856-gutauxhWAwn6.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21856-gutauxhWAwn6.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21856-wtSHgeHFmzdG.jpg', 'Taking off right after the last episode of the first season. The school is temporarily closed due to security. When U.A. restarts, it is announced that the highly anticipated School Sports Festival will soon be taking place. All classes: Hero, Support, General and Business will be participating. Tournaments all round will decide who is the top Hero in training. (Source: Anime News Network)', 79, 665905, 25, 'FINISHED', 'TV'),
    (110277, '{"romaji":"Shingeki no Kyojin: The Final Season","english":"Attack on Titan Final Season","native":"進撃の巨人 The Final Season","userPreferred":"Shingeki no Kyojin: The Final Season"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx110277-sKUNXAsWMNFw.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx110277-sKUNXAsWMNFw.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/110277-iuGn6F5bK1U1.jpg', 'It’s been four years since the Scout Regiment reached the shoreline, and the world looks different now. Things are heating up as the fate of the Scout Regiment—and the people of Paradis—are determined at last. However, Eren is missing. Will he reappear before age-old tensions between Marleyans and Eldians result in the war of all wars? (Source: Crunchyroll)', 87, 656502, 16, 'FINISHED', 'TV'),
    (127230, '{"romaji":"Chainsaw Man","english":"Chainsaw Man","native":"チェンソーマン","userPreferred":"Chainsaw Man"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx127230-DdP4vAdssLoz.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx127230-DdP4vAdssLoz.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/127230-o8IRwCGVr9KW.jpg', 'Denji is a teenage boy living with a Chainsaw Devil named Pochita. Due to the debt his father left behind, he has been living a rock-bottom life while repaying his debt by harvesting devil corpses with Pochita. One day, Denji is betrayed and killed. As his consciousness fades, he makes a contract with Pochita and gets revived as "Chainsaw Man" — a man with a devil''s heart. (Source: Crunchyroll)', 83, 652365, 12, 'FINISHED', 'TV'),
    (101759, '{"romaji":"Yakusoku no Neverland","english":"The Promised Neverland","native":"約束のネバーランド","userPreferred":"Yakusoku no Neverland"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx101759-8UR7r9MNVpz2.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101759-8UR7r9MNVpz2.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101759-MhlCoeqnODso.jpg', 'Emma, Norman and Ray are the brightest kids at the Grace Field House orphanage. And under the care of the woman they refer to as “Mom,” all the kids have enjoyed a comfortable life. Good food, clean clothes and the perfect environment to learn—what more could an orphan ask for? One day, though, Emma and Norman uncover the dark truth of the outside world they are forbidden from seeing. (Source: VIZ Media)', 83, 643303, 12, 'FINISHED', 'TV'),
    (20755, '{"romaji":"Ansatsu Kyoushitsu","english":"Assassination Classroom","native":"暗殺教室","userPreferred":"Ansatsu Kyoushitsu"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20755-dWrhs569YGUO.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20755-dWrhs569YGUO.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20755-D4ipww9U8YkC.jpg', 'The students of class 3-E have a mission: kill their teacher before graduation. He has already destroyed the moon, and has promised to destroy the Earth if he can not be killed within a year. But how can this class of misfits kill a tentacled monster, capable of reaching Mach 20 speed, who may be the best teacher any of them have ever had?', 79, 639275, 22, 'FINISHED', 'TV'),
    (21507, '{"romaji":"Mob Psycho 100","english":"Mob Psycho 100","native":"モブサイコ100","userPreferred":"Mob Psycho 100"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21507-6YUSbh2m0N1p.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21507-6YUSbh2m0N1p.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21507-Qx8bGsLXUgLo.jpg', 'The story revolves around "Mob," a boy who will explode if his emotional capacity reaches 100%. This boy with psychic powers earned his nickname "Mob" because he does not stand out among other people. He keeps his psychic powers bottled up so he can live normally, but if his emotional level reaches 100, something will overwhelm his entire body. (Source: Anime News Network)', 84, 639093, 12, 'FINISHED', 'TV'),
    (21355, '{"romaji":"Re:Zero kara Hajimeru Isekai Seikatsu","english":"Re:ZERO -Starting Life in Another World-","native":"Re:ゼロから始める異世界生活","userPreferred":"Re:Zero kara Hajimeru Isekai Seikatsu"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21355-wRVUrGxpvIQQ.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21355-wRVUrGxpvIQQ.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21355-f9SjOfEJMk5P.jpg', 'In the story, Subaru Natsuki is an ordinary high school student who is lost in an alternate world, where he is rescued by a beautiful, silver-haired girl. He stays near her to return the favor, but the destiny she is burdened with is more than Subaru can imagine. Enemies attack one by one, and both of them are killed. He then finds out he has the power to rewind death, back to the time he first came to this world. But only he remembers what has happened since. (Source: Anime News Network) Notes: - The first episode aired with a runtime of ~50 minutes as opposed to the standard 25 minute long episode. - In the Winter 2020 season, Re:ZERO was rebroadcast and re-edited to fit into an hour time-slot. This edit included the first OVA and added slight modifications to certain scenes throughout. It also added an additional scene at the end of the final episode.', 81, 638060, 25, 'FINISHED', 'TV'),
    (20665, '{"romaji":"Shigatsu wa Kimi no Uso","english":"Your lie in April","native":"四月は君の嘘","userPreferred":"Shigatsu wa Kimi no Uso"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20665-TLgkL8T8IRFd.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20665-TLgkL8T8IRFd.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20665-j4kSsfhfkM24.jpg', 'Piano prodigy Arima Kousei dominated the competition and all child musicians knew his name. But after his mother, who was also his instructor, passed away, he had a mental breakdown while performing at a recital. This resulted in him no longer being able to hear the sound of his piano playing. Two years later, Kousei hasn’t touched the piano and views the world without any flair or color. He was content at living out his life with his good friends Tsubaki and Watari until, one day, a girl changed everything. Miyazono Kaori is a pretty, free spirited violinist whose playing style reflects her personality. Kaori helps Kousei return to the music world and show that it should be free and mold breaking unlike the structured and rigid style Kousei was used to.', 84, 625035, 22, 'FINISHED', 'TV'),
    (104578, '{"romaji":"Shingeki no Kyojin Season 3 Part 2","english":"Attack on Titan Season 3 Part 2","native":"進撃の巨人 Season３ Part.2","userPreferred":"Shingeki no Kyojin Season 3 Part 2"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx104578-k61nx3LPjvgd.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx104578-k61nx3LPjvgd.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/104578-z7SadpYEuAsy.jpg', 'The battle to retake Wall Maria begins now! With Eren’s new hardening ability, the Scouts are confident they can seal the wall and take back Shiganshina District. If they succeed, Eren can finally unlock the secrets of the basement—and the world. But danger lies in wait as Reiner, Bertholdt, and the Beast Titan have plans of their own. Could this be humanity’s final battle for survival? (Source: Funimation)', 89, 623806, 10, 'FINISHED', 'TV'),
    (1735, '{"romaji":"NARUTO: Shippuuden","english":"Naruto: Shippuden","native":"NARUTO -ナルト- 疾風伝","userPreferred":"NARUTO: Shippuuden"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx1735-kGfVm0YqCPcu.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1735-kGfVm0YqCPcu.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1735.jpg', 'Naruto: Shippuuden is the continuation of the original animated TV series Naruto. The story revolves around an older and slightly more matured Uzumaki Naruto and his quest to save his friend Uchiha Sasuke from the grips of the snake-like Shinobi, Orochimaru. After 2 and a half years Naruto finally returns to his village of Konoha, and sets about putting his ambitions to work, though it will not be easy, as he has amassed a few (more dangerous) enemies, in the likes of the shinobi organization; Akatsuki. (Source: Anime News Network)', 82, 623178, 500, 'FINISHED', 'TV'),
    (21234, '{"romaji":"Boku dake ga Inai Machi","english":"ERASED","native":"僕だけがいない街","userPreferred":"Boku dake ga Inai Machi"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21234-XmqW39aQ9o7O.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21234-XmqW39aQ9o7O.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21234-7lfSSPoMmwr2.jpg', 'Satoru Fujinuma is a 29 year old manga artist struggling to make a name for himself following his debut. But, that was not the only thing in his life that Satoru was feeling frustrated about… He has a unique supernatural ability of being forced to prevent deaths and catastrophes by being sent back in time before the incident occurred, repeating time until the accident is prevented. One day, he gets involved in an accident that has him framed as a murderer. Desperate to save the victim, he sends himself back in time only to find himself as a grade-schooler one month before fellow classmate Kayo Hinazuki went missing. Satoru now embarks on a new quest: to save Kayo and solve the mystery behind her disappearance.', 81, 616304, 12, 'FINISHED', 'TV'),
    (100166, '{"romaji":"Boku no Hero Academia 3","english":"My Hero Academia Season 3","native":"僕のヒーローアカデミア３","userPreferred":"Boku no Hero Academia 3"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx100166-jUCZYbzn2XLw.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx100166-jUCZYbzn2XLw.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100166-k7RXwN5vZg0r.jpg', 'Summer is here, and the heroes of Class 1-A and 1-B are in for the toughest training camp of their lives! A group of seasoned pros pushes everyone''s Quirks to new heights as the students face one overwhelming challenge after another. Braving the elements in this secret location becomes the least of their worries when routine training turns into a critical struggle for survival. (Source: Crunchyroll)', 79, 610413, 25, 'FINISHED', 'TV'),
    (9253, '{"romaji":"Steins;Gate","english":"Steins;Gate","native":"シュタインズ・ゲート","userPreferred":"Steins;Gate"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx9253-tIUXF2gfU8Sg.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9253-tIUXF2gfU8Sg.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n9253-JIhmKgBKsWUN.jpg', 'Self-proclaimed mad scientist Okabe Rintarou lives in a small room in Akihabara, where he invents "future gadgets" with fellow lab members Shiina Mayuri, his air-headed childhood friend, and Hashida Itaru, an otaku hacker. The three pass the time by tinkering with their latest creation, a "Phone Microwave" that can be controlled through text messages. The lab members soon face a string of mysterious incidents that lead to a game-changing discovery: the Phone Microwave can send emails to the past and thus alter history. Adapted from the critically acclaimed visual novel by 5pb. and Nitroplus, Steins;Gate takes Okabe to the depths of scientific theory and human despair as he faces the dire consequences of changing the past.', 89, 606875, 24, 'FINISHED', 'TV'),
    (97940, '{"romaji":"Black Clover","english":"Black Clover","native":"ブラッククローバー","userPreferred":"Black Clover"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx97940-fyh8o7gNbha0.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97940-fyh8o7gNbha0.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97940-1URQdQ4U1a0b.jpg', 'In a world where magic is everything, Asta and Yuno are both found abandoned at a church on the same day. While Yuno is gifted with exceptional magical powers, Asta is the only one in this world without any. At the age of fifteen, both receive grimoires, magic books that amplify their holder’s magic. Asta’s is a rare Grimoire of Anti-Magic that negates and repels his opponent’s spells. Being opposite but good rivals, Yuno and Asta are ready for the hardest of challenges to achieve their common dream: to be the Wizard King. Giving up is never an option! (Source: Crunchyroll)', 79, 604528, 170, 'FINISHED', 'TV'),
    (20464, '{"romaji":"Haikyuu!!","english":"HAIKYU!!","native":"ハイキュー!!","userPreferred":"Haikyuu!!"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20464-ooZUyBe4ptp9.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20464-ooZUyBe4ptp9.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20464-PpYjO9cPN1gs.jpg', 'Inspired after watching a volleyball ace nicknamed "Little Giant" in action, small-statured Shouyou Hinata revives the volleyball club at his middle school. The newly-formed team even makes it to a tournament; however, their first match turns out to be their last when they are brutally squashed by the "King of the Court," Tobio Kageyama. Hinata vows to surpass Kageyama, and so after graduating from middle school, he joins Karasuno High School''s volleyball team—only to find that his sworn rival, Kageyama, is now his teammate. Thanks to his short height, Hinata struggles to find his role on the team, even with his superior jumping power. Surprisingly, Kageyama has his own problems that only Hinata can help with, and learning to work together appears to be the only way for the team to be successful. Based on Haruichi Furudate''s popular shounen manga of the same name, Haikyuu!! is an exhilarating and emotional sports comedy following two determined athletes as they attempt to patch a heated rivalry in order to make their high school volleyball team the best in Japan. [Written by MAL Rewrite]', 83, 593458, 25, 'FINISHED', 'TV'),
    (101291, '{"romaji":"Seishun Buta Yarou wa Bunny Girl Senpai no Yume wo Minai","english":"Rascal Does Not Dream of Bunny Girl Senpai","native":"青春ブタ野郎はバニーガール先輩の夢を見ない","userPreferred":"Seishun Buta Yarou wa Bunny Girl Senpai no Yume wo Minai"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx101291-wfEdgPqtfU0l.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101291-wfEdgPqtfU0l.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n101291-fqIUvQ6apEtD.jpg', 'There''s a rumor about a mysterious phenomenon called "puberty syndrome." For example, Sakuta Azusagawa is a high school student who suddenly sees a bunny girl appear in front of him. The girl is actually a girl named Mai Sakurajima, who is Sakuta''s upperclassman who is also a famous actress who has gone on hiatus from the entertainment industry. For some reason, the people around Mai cannot see her bunny-girl figure. Sakuta sets out to solve this mystery, and as he spends time with Mai, he learns her secret feelings. Other heroines who have "puberty syndrome" start to appear in front of Sakuta. (Source: Anime News Network)', 81, 592084, 13, 'FINISHED', 'TV'),
    (140960, '{"romaji":"SPY×FAMILY","english":"SPY x FAMILY","native":"SPY×FAMILY","userPreferred":"SPY×FAMILY"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx140960-Kb6R5nYQfjmP.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx140960-Kb6R5nYQfjmP.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/140960-Z7xSvkRxHKfj.jpg', 'Everyone has a part of themselves they cannot show to anyone else. At a time when all nations of the world were involved in a fierce war of information happening behind closed doors, Ostania and Westalis had been in a state of cold war against one another for decades. The Westalis Intelligence Services'' Eastern-Focused Division (WISE) sends their most talented spy, "Twilight," on a top-secret mission to investigate the movements of Donovan Desmond, the chairman of Ostania''s National Unity Party, who is threatening peace efforts between the two nations. This mission is known as "Operation Strix." It consists of "putting together a family in one week in order to infiltrate social gatherings organized by the elite school that Desmond''s son attends." "Twilight" takes on the identity of psychiatrist Loid Forger and starts looking for family members. But Anya, the daughter he adopts, turns out to have the ability to read people''s minds, while his wife, Yor, is an assassin! With it being in each of their own interests to keep these facts hidden, they start living together while concealing their true identities from one another. World peace is now in the hands of this brand-new family as t', 83, 583335, 12, 'FINISHED', 'TV'),
    (101921, '{"romaji":"Kaguya-sama wa Kokurasetai: Tensaitachi no Renai Zunousen","english":"Kaguya-sama: Love is War","native":"かぐや様は告らせたい～天才たちの恋愛頭脳戦～","userPreferred":"Kaguya-sama wa Kokurasetai: Tensaitachi no Renai Zunousen"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx101921-ufrjLzhSz7L1.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101921-ufrjLzhSz7L1.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101921-GgvvFhlNhzlF.jpg', 'Known for being both brilliant and powerful, Miyuki Shirogane and Kaguya Shinomiya lead the illustrious Shuchiin Academy as near equals. And everyone thinks they’d make a great couple. Pride and arrogance are in ample supply, so the only logical move is to trick the other into instigating a date! Who will come out on top in this psychological war where the first move is the only one that matters? (Source: Aniplex)', 83, 570249, 12, 'FINISHED', 'TV'),
    (105333, '{"romaji":"Dr. STONE","english":"Dr. STONE","native":"Dr.STONE","userPreferred":"Dr. STONE"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx105333-GybuoSoOZfpH.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx105333-GybuoSoOZfpH.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/105333-KWKGvBM8Hyga.jpg', 'After five years of harboring unspoken feelings, high-schooler Taiju Ooki is finally ready to confess his love to Yuzuriha Ogawa. Just when Taiju begins his confession however, a blinding green light strikes the Earth and petrifies mankind around the world— turning every single human into stone. Several millennia later, Taiju awakens to find the modern world completely nonexistent, as nature has flourished in the years humanity stood still. Among a stone world of statues, Taiju encounters one other living human: his science-loving friend Senkuu, who has been active for a few months. Taiju learns that Senkuu has developed a grand scheme—to launch the complete revival of civilization with science. Taiju''s brawn and Senkuu''s brains combine to forge a formidable partnership, and they soon uncover a method to revive those petrified. However, Senkuu''s master plan is threatened when his ideologies are challenged by those who awaken. All the while, the reason for mankind''s petrification remains unknown. (Source: MAL Rewrite)', 81, 565660, 24, 'FINISHED', 'TV'),
    (101348, '{"romaji":"VINLAND SAGA","english":"Vinland Saga","native":"ヴィンランド・サガ","userPreferred":"VINLAND SAGA"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx101348-2fhDFPCuMNiz.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101348-2fhDFPCuMNiz.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101348-pivKKffCAwAY.jpg', 'Thorfinn is son to one of the Vikings'' greatest warriors, but when his father is killed in battle by the mercenary leader Askeladd, he swears to have his revenge. Thorfinn joins Askeladd''s band in order to challenge him to a duel, and ends up caught in the middle of a war for the crown of England. (Source: Kodansha USA)', 87, 560097, 24, 'FINISHED', 'TV'),
    (21827, '{"romaji":"Violet Evergarden","english":"Violet Evergarden","native":"ヴァイオレット・エヴァーガーデン","userPreferred":"Violet Evergarden"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21827-ubzq619ZA2E9.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21827-ubzq619ZA2E9.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21827-ROucgYiiiSpR.jpg', 'A certain point in time, in the continent of Telesis. The great war which divided the continent into North and South has ended after four years, and the people are welcoming a new generation. Violet Evergarden, a young girl formerly known as “the weapon”, has left the battlefield to start a new life at CH Postal Service. There, she is deeply moved by the work of “Auto Memories Dolls”, who carry people''s thoughts and convert them into words. Violet begins her journey as an Auto Memories Doll, and comes face to face with various people''s emotions and differing shapes of love. There are words Violet heard on the battlefield, which she cannot forget. These words were given to her by someone she holds dear, more than anyone else. She does not yet know their meaning but she searches to find it. (Source: Anime News Network)', 85, 557710, 13, 'FINISHED', 'TV'),
    (124080, '{"romaji":"Horimiya","english":"Horimiya","native":"ホリミヤ","userPreferred":"Horimiya"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx124080-3i22mRVPBS0T.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx124080-3i22mRVPBS0T.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/124080-ARyLAHHgikRq.jpg', 'A secret life is the one thing they have in common. At school, Hori is a prim and perfect social butterfly, but the truth is she''s a brash homebody. Meanwhile, under a gloomy facade, Miyamura hides a gentle heart, along with piercings and tattoos. In a chance meeting, they both reveal a side they''ve never shown. Could this blossom into something new? (Source: Funimation)', 81, 555679, 13, 'FINISHED', 'TV'),
    (4224, '{"romaji":"Toradora!","english":"Toradora!","native":"とらドラ！","userPreferred":"Toradora!"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx4224-PXVMBLNwy2aF.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx4224-PXVMBLNwy2aF.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4224-iPUOHdMde27j.jpg', 'Ryuuji Takasu is a gentle high school student with a love for housework; but in contrast to his kind nature, he has an intimidating face that often gets him labeled as a delinquent. On the other hand is Taiga Aisaka, a small, doll-like student, who is anything but a cute and fragile girl. Equipped with a wooden katana and feisty personality, Taiga is known throughout the school as the "Palmtop Tiger." One day, an embarrassing mistake causes the two students to cross paths. Ryuuji discovers that Taiga actually has a sweet side: she has a crush on the popular vice president, Yuusaku Kitamura, who happens to be his best friend. But things only get crazier when Ryuuji reveals that he has a crush on Minori Kushieda—Taiga''s best friend! Toradora! is a romantic comedy that follows this odd duo as they embark on a quest to help each other with their respective crushes, forming an unlikely alliance in the process.', 77, 551765, 25, 'FINISHED', 'TV'),
    (19815, '{"romaji":"No Game No Life","english":"No Game, No Life","native":"ノーゲーム・ノーライフ","userPreferred":"No Game No Life"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b19815-sEOQ9yQaPKlk.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b19815-sEOQ9yQaPKlk.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/19815-BqbuD0wyBS3P.jpg', 'Bored with life and considering the real world to be just a “crappy game,” savvy sibling shut-ins Sora and Shiro have withdrawn into their own fantasy world filled with video games. However, one day they find themselves summoned to another world by a boy who calls himself “God,” their abilities are about to be put to the ultimate test! Now not only their fates — but the fate of all of humanity — will be decided by a series of games that may just be the hardest these super-geniuses have ever faced! (Source: Sentai Filmworks, edited)', 77, 549281, 12, 'FINISHED', 'TV'),
    (20613, '{"romaji":"Akame ga Kill!","english":"Akame ga Kill!","native":"アカメが斬る！","userPreferred":"Akame ga Kill!"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20613-HXHpec4bemk5.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20613-HXHpec4bemk5.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20613-CoEQF4qKiWDX.jpg', 'In a land where corruption rules and a ruthless Prime Minister has turned the puppet Emperor''s armies of soldiers, assassins and secret police against the people, only one force dares to stand against them: Night Raid, an elite team of relentless killers, each equipped with an Imperial Arm - legendary weapons with unique and incredible powers created in the distant past. Rescued from a fate worse than death by Night Raid, young Tatsumi is offered the chance to join their lethal ranks… but it''s a deadly choice, as few can master an Imperial Arm and even fewer survive when two Arms go against each other in combat. The battle is on, and only the strongest will make it out alive. (Source: Sentai Filmworks)', 73, 549218, 24, 'FINISHED', 'TV'),
    (20447, '{"romaji":"Noragami","english":"Noragami","native":"ノラガミ","userPreferred":"Noragami"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20447-EoQXeygHaVCK.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20447-EoQXeygHaVCK.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20447-nlgQQzcgWbgw.jpg', 'Minor god Yato is down on his luck. Fed up with his slacker lifestyle, his partner abruptly quits. He has no money, no worshippers, and no shrine to call home. But just when things are starting to seem hopeless, a bus accident forces him to cross paths with Hiyori Iki, a sweet and perky high school girl. After the accident, Hiyori''s soul has a bad habit of slipping out of her body, and after enlisting Yato''s help to get her back to normal, she begins to fall into the world of spirits and gods. But Hiyori''s not the only one who''s keeping tabs on Yato. A god from Yato''s past is back, and he''s not interested in a friendly reunion. (Source: Funimation)', 78, 547082, 12, 'FINISHED', 'TV'),
    (104276, '{"romaji":"Boku no Hero Academia 4","english":"My Hero Academia Season 4","native":"僕のヒーローアカデミア４","userPreferred":"Boku no Hero Academia 4"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx104276-SnEowMvesWIE.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx104276-SnEowMvesWIE.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/104276-PQO1pcNzzWT0.jpg', 'The villain world teeters on the brink of war now that All For One is out of the picture. Shigaraki of the League of Villains squares off with Overhaul of the yakuza, vying for total control of the shadows. Meanwhile, Deku gets tangled in another dangerous internship as he struggles to keep pace with his upperclassman—Mirio. (Source: Crunchyroll)', 78, 541458, 25, 'FINISHED', 'TV'),
    (20789, '{"romaji":"Nanatsu no Taizai","english":"The Seven Deadly Sins","native":"七つの大罪","userPreferred":"Nanatsu no Taizai"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20789-Ma5ouSYPkru9.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20789-Ma5ouSYPkru9.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20789-qwG9GcxIrmVE.jpg', 'When they were accused of trying to overthrow the monarchy, the feared warriors the Seven Deadly Sins were sent into exile. Princess Elizabeth discovers the truth - the Sins were framed by the king''s guard, the Holy Knights - too late to prevent them from assassinating her father and seizing the throne! Now the princess is on the run, seeking the Sins to help her reclaim the kingdom. But the first Sin she meets, Meliodas, is a little innkeeper with a talking pig. He doesn''t even have a real sword! Have the legends of the Sins'' strength been exaggerated? (Source: Anime News Network)', 72, 538509, 24, 'FINISHED', 'TV'),
    (269, '{"romaji":"BLEACH","english":"Bleach","native":"BLEACH","userPreferred":"BLEACH"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx269-d2GmRkJbMopq.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx269-d2GmRkJbMopq.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/269-08ar2HJOUAuL.jpg', 'Ichigo Kurosaki is a rather normal high school student apart from the fact he has the ability to see ghosts. This ability never impacted his life in a major way until the day he encounters the Shinigami Kuchiki Rukia, who saves him and his family''s lives from a Hollow, a corrupt spirit that devours human souls. Wounded during the fight against the Hollow, Rukia chooses the only option available to defeat the monster and passes her Shinigami powers to Ichigo. Now forced to act as a substitute until Rukia recovers, Ichigo hunts down the Hollows that plague his town.', 79, 537053, 366, 'FINISHED', 'TV'),
    (21202, '{"romaji":"Kono Subarashii Sekai ni Shukufuku wo!","english":"KONOSUBA -God''s blessing on this wonderful world!","native":"この素晴らしい世界に祝福を！","userPreferred":"Kono Subarashii Sekai ni Shukufuku wo!"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21202-mPOr80AEjUcZ.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21202-mPOr80AEjUcZ.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21202-UWijdV7RMnXo.jpg', 'Kazuma Satou decides that today is the day to get out of the house for a bit. Since he dies, pointlessly, it''s clearly a bad choice. The goddess who greets him in the afterlife, however, offers him a chance to be reborn in a world not unlike that of a video game, and as a bonus she''ll even throw in a cool item or power! Can''t possibly be a bad choice, right? Except he arrives with no money at all, dead average skills, and his "bonus" isn''t useful at all--since he picked the goddess, Aqua, herself. How are the two of them supposed to defeat the evil Devil King and live happily ever after? Well, for them, it probably starts with day laboring rather than adventuring. And it''s only going to get more disappointing from there! (Source: Crunchyroll)', 79, 528727, 10, 'FINISHED', 'TV'),
    (112151, '{"romaji":"Kimetsu no Yaiba: Mugen Ressha-hen","english":"Demon Slayer -Kimetsu no Yaiba- The Movie: Mugen Train","native":"鬼滅の刃 無限列車編","userPreferred":"Kimetsu no Yaiba: Mugen Ressha-hen"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx112151-1qlQwPB1RrJe.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx112151-1qlQwPB1RrJe.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112151-eHCBz19nf2yC.jpg', 'This Demon Slayer movie sees Tanjiro Kamado and friends from the Demon Slayer corps board the Infinity Train on a new mission to investigate a mysterious series of disappearances, perpetrated by a demon who has been tormenting people and killing the demon slayers who oppose it.', 84, 518319, 1, 'FINISHED', 'MOVIE'),
    (1575, '{"romaji":"Code Geass: Hangyaku no Lelouch","english":"Code Geass: Lelouch of the Rebellion","native":"コードギアス 反逆のルルーシュ","userPreferred":"Code Geass: Hangyaku no Lelouch"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx1575-hsmWM2ydNm1m.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1575-hsmWM2ydNm1m.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1575.jpg', 'On August 10th of the year 2010 the Holy Empire of Britannia began a campaign of conquest, its sights set on Japan. Operations were completed in one month thanks to Britannia''s deployment of new mobile humanoid armor vehicles dubbed Knightmare Frames. Japan''s rights and identity were stripped away, the once proud nation now referred to as Area 11. Its citizens, Elevens, are forced to scratch out a living while the Britannian aristocracy lives comfortably within their settlements. Pockets of resistance appear throughout Area 11, working towards independence for Japan. Lelouch, an exiled Imperial Prince of Britannia posing as a student, finds himself in the heart of the ongoing conflict for the island nation. Through a chance meeting with a mysterious girl named C.C., Lelouch gains his Geass, the power of the king. Now endowed with absolute dominance over any person, Lelouch may finally realize his goal of bringing down Britannia from within! (Source: Bandai Entertainment)', 85, 513390, 25, 'FINISHED', 'TV'),
    (99423, '{"romaji":"Darling in the Franxx","english":"DARLING in the FRANXX","native":"ダーリン・イン・ザ・フランキス","userPreferred":"Darling in the Franxx"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/nx99423-8MBxtwCeHf8B.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx99423-8MBxtwCeHf8B.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99423-OQfem628gdxD.jpg', 'The distant future: Humanity established the mobile fort city, Plantation, upon the ruined wasteland. Within the city were pilot quarters, Mistilteinn, otherwise known as the “Birdcage.” That is where the children live... Their only mission in life was the fight. Their enemies are the mysterious giant organisms known as Kyoryu. The children operate robots known as FRANXX in order to face these still unseen enemies. Among them was a boy who was once called a child prodigy: Code number 016, Hiro. One day, a mysterious girl called Zero Two appears in front of Hiro. “I’ve found you, my Darling.” (Source: Crunchyroll)', 69, 510059, 24, 'FINISHED', 'TV'),
    (20623, '{"romaji":"Kiseijuu: Sei no Kakuritsu","english":"Parasyte -the maxim-","native":"寄生獣 セイの格率","userPreferred":"Kiseijuu: Sei no Kakuritsu"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20623-dUARfggnNDOe.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20623-dUARfggnNDOe.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20623-xb9PPf8rGOsG.jpg', 'They arrive in silence and darkness. They descend from the skies. They have a hunger for human flesh. They are everywhere. They are parasites, alien creatures who must invade–and take control of–a human host to survive. And once they have infected their victims, they can assume any deadly form they choose: monsters with giant teeth, winged demons, creatures with blades for hands. But most have chosen to conceal their lethal purpose behind ordinary human faces. So no one knows their secret–except an ordinary high school student. Shin is battling for control of his own body against an alien parasite, but can he find a way to warn humanity of the horrors to come? (Source: Del Rey)', 81, 509341, 24, 'FINISHED', 'TV'),
    (145064, '{"romaji":"Jujutsu Kaisen 2nd Season","english":"JUJUTSU KAISEN Season 2","native":"呪術廻戦 第2期","userPreferred":"Jujutsu Kaisen 2nd Season"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx145064-hSNRJM03pvv1.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx145064-hSNRJM03pvv1.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/145064-esDtAY2He7sk.jpg', 'The past comes to light when second-year students Satoru Gojou and Suguru Getou are tasked with escorting young Riko Amanai to Master Tengen. But when a non-sorcerer user tries to kill them, their mission to protect the Star Plasma Vessel threatens to turn them into bitter enemies and cement their destinies—one as the world’s strongest sorcerer, and the other its most twisted curse user! (Source: Crunchyroll)', 86, 507061, 23, 'FINISHED', 'TV'),
    (30, '{"romaji":"Shin Seiki Evangelion","english":"Neon Genesis Evangelion","native":"新世紀エヴァンゲリオン","userPreferred":"Shin Seiki Evangelion"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx30-AI1zr74Dh4ye.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx30-AI1zr74Dh4ye.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/30-gEMoHHIqxDgN.jpg', 'In the year 2015, the Angels, huge, tremendously powerful, alien war machines, appear in Tokyo for the second time. The only hope for Mankind''s survival lies in the Evangelion, a humanoid fighting machine developed by NERV, a special United Nations agency. Capable of withstanding anything the Angels can dish out, the Evangelion''s one drawback lies in the limited number of people able to pilot them. Only a handful of teenagers, all born fourteen years ago, nine months after the Angels first appeared, are able to interface with the Evangelion. One such teenager is Shinji Ikari, whose father heads the NERV team that developed and maintains the Evangelion. Thrust into a maelstrom of battle and events that he does not understand, Shinji is forced to plumb the depths of his own inner resources for the courage and strength to not only fight, but to survive, or risk losing everything. (Source: AniDB) Note: Later releases include edited versions of Episodes 21-24 called the "Director''s Cut" with some visual editing and adding extra scenes that previously appeared in the theatrical recap ''Death''.', 83, 505842, 26, 'FINISHED', 'TV'),
    (154587, '{"romaji":"Sousou no Frieren","english":"Frieren: Beyond Journey’s End","native":"葬送のフリーレン","userPreferred":"Sousou no Frieren"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx154587-qQTzQnEJJ3oB.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx154587-qQTzQnEJJ3oB.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/154587-ivXNJ23SM1xB.jpg', 'The adventure is over but life goes on for an elf mage just beginning to learn what living is all about. Elf mage Frieren and her courageous fellow adventurers have defeated the Demon King and brought peace to the land. But Frieren will long outlive the rest of her former party. How will she come to understand what life means to the people around her? Decades after their victory, the funeral of one her friends confronts Frieren with her own near immortality. Frieren sets out to fulfill the last wishes of her comrades and finds herself beginning a new adventure… (Source: Crunchyroll)', 90, 498591, 28, 'FINISHED', 'TV'),
    (142329, '{"romaji":"Kimetsu no Yaiba: Yuukaku-hen","english":"Demon Slayer: Kimetsu no Yaiba Entertainment District Arc","native":"鬼滅の刃 遊郭編","userPreferred":"Kimetsu no Yaiba: Yuukaku-hen"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx142329-kET1PIXJv2eW.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx142329-kET1PIXJv2eW.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/142329-i413SzLmToZN.jpg', 'After visiting the Rengoku residence, Tanjirou and his comrades volunteer for a mission within the Entertainment District, a place where desires are sold and demons dwell. They journey alongside the flashy Sound Hashira, Tengen Uzui, in search of a monstrous foe terrorizing the town. Sworn to slay creatures of the night, the hunt continues. (Source: Funimation) Note: - The first episode aired with a runtime of ~47 minutes. - The last episode aired with a runtime of ~33 minutes.', 85, 495805, 11, 'FINISHED', 'TV'),
    (105310, '{"romaji":"Enen no Shouboutai","english":"Fire Force","native":"炎炎ノ消防隊","userPreferred":"Enen no Shouboutai"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx105310-2PKUvoaA6fTn.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx105310-2PKUvoaA6fTn.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/105310-ygGL9yweZM2Q.jpg', 'Year 198 of the Solar Era in Tokyo, special fire brigades are fighting against a phenomenon called spontaneous human combustion where human beings are turned into living infernos called "Infernals.” While the Infernals are first-generation cases of spontaneous human combustion, later generations possess the ability to manipulate flames while retaining human form. Shinra Kusakabe, a youth who gained the nickname Devil’s Footprints for his ability to ignite his feet at will, joins the Special Fire Force Company 8 which composes of other flames users as they work to extinguish any Infernals they encounter. As a faction that is creating Infernals appears, Shinra begins to uncover the truth behind a mysterious fire that caused the death of his family twelve years ago. (Source: Official Website)', 76, 493746, 24, 'FINISHED', 'TV'),
    (199, '{"romaji":"Sen to Chihiro no Kamikakushi","english":"Spirited Away","native":"千と千尋の神隠し","userPreferred":"Sen to Chihiro no Kamikakushi"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx199-sWefXJvXkDOb.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx199-sWefXJvXkDOb.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/199-Sm2RU5PSqw7T.jpg', 'On the way to their new home, 10-year-old Chihiro Ogino''s family stumbles upon a deserted theme park. Intrigued, the family investigates the park, though unbeknownst to them, it is secretly inhabited by spirits who sleep by day and appear at night. When Chihiro''s mother and father eat food from a restaurant in the street, angry spirits turn them into pigs. Furthermore, a wide sea has appeared between the spirit world and the human one, trapping Chihiro, the sole human, in a land of spirits. Luckily for her though, a mysterious boy named Haku appears, claiming to know her from the past. Under his instructions, Chihiro secures a job in the bathhouse where Haku works. With only her courage and some new found friends to aid her, Chihiro embarks on a journey to turn her parents back to their original forms and return home.', 86, 489621, 1, 'FINISHED', 'MOVIE'),
    (14719, '{"romaji":"JoJo no Kimyou na Bouken (TV)","english":"JoJo''s Bizarre Adventure (TV)","native":"ジョジョの奇妙な冒険 (TV)","userPreferred":"JoJo no Kimyou na Bouken (TV)"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx14719-VT5dRzTBSZ0w.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14719-VT5dRzTBSZ0w.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/14719-m7Hv2AxcNNjM.jpg', 'Beginning its tale in 19th century England, young aristocrat Jonathan Joestar finds himself locked in bitter rivalry with Dio Brando, a low-born boy who Jonathan''s father took under his wing after the death of Dio''s father. Discontent with his station in life, Dio''s fathomless lust to reign over all eventually leads him to seek the supernatural powers of an ancient Aztec stone mask in the Joestar''s possession—an artifact that will forever change the destiny of Dio and Jonathan for generations to come. Fifty years later, in 1938 New York City, Jonathan''s grandson Joseph Joestar must take up his grandfather''s mission and master the abilities necessary to destroy the stone mask and its immensely powerful creators who threaten humanity''s very existence, the Pillar Men. (Source: Anime News Network)', 77, 489348, 26, 'FINISHED', 'TV'),
    (1, '{"romaji":"Cowboy Bebop","english":"Cowboy Bebop","native":"カウボーイビバップ","userPreferred":"Cowboy Bebop"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx1-GCsPm7waJ4kS.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx1-GCsPm7waJ4kS.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1-OquNCNB6srGe.jpg', 'Enter a world in the distant future, where Bounty Hunters roam the solar system. Spike and Jet, bounty hunting partners, set out on journeys in an ever struggling effort to win bounty rewards to survive. While traveling, they meet up with other very interesting people. Could Faye, the beautiful and ridiculously poor gambler, Edward, the computer genius, and Ein, the engineered dog be a good addition to the group?', 86, 476405, 26, 'FINISHED', 'TV'),
    (97668, '{"romaji":"One Punch Man 2","english":"One-Punch Man Season 2","native":"ワンパンマン 2","userPreferred":"One Punch Man 2"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx97668-nC8gQrXVxt7k.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97668-nC8gQrXVxt7k.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97668-8Yo3iH2fxbKR.jpg', 'Saitama is a hero who only became a hero for fun. After three years of “special training,” he’s become so strong that he’s practically invincible. In fact, he’s too strong—even his mightiest opponents are taken out with a single punch. Now, the great seer Madame Shibabawa’s prediction about the Earth being doomed seems to be coming true as the frequency of monster incidents escalates. Alongside Genos, his faithful disciple, Saitama begins his official hero duties as a member of the Hero Association, while Garou, a man utterly fascinated by monsters, makes his appearance.', 74, 475517, 12, 'FINISHED', 'TV'),
    (101280, '{"romaji":"Tensei Shitara Slime Datta Ken","english":"That Time I Got Reincarnated as a Slime","native":"転生したらスライムだった件","userPreferred":"Tensei Shitara Slime Datta Ken"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx101280-tDxCVJm714nt.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101280-tDxCVJm714nt.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101280-9t7J3774n955.jpg', 'Lonely thirty-seven-year-old Satoru Mikami is stuck in a dead-end job, unhappy with his mundane life, but after dying at the hands of a robber, he awakens to a fresh start in a fantasy realm...as a slime monster! As he acclimates to his goopy new existence, his exploits with the other monsters set off a chain of events that will change his new world forever! (Source: Yen Press)', 80, 475261, 24, 'FINISHED', 'TV'),
    (20931, '{"romaji":"Death Parade","english":"Death Parade","native":"デス・パレード","userPreferred":"Death Parade"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/nx20931-bktYqOcxPERi.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx20931-bktYqOcxPERi.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20931-xDhiTPZmtS3u.jpg', 'When two people die at the same time, they’re sent to a place that’s neither heaven nor hell—a lavish bar between worlds where the stakes are high and the rules are simple: if you win you live again, if you die… you’re gone for good. Decim is the bartender charged with serving the souls who enter Quindecim. He may make a mean cocktail, but his true profession is to play the role of arbiter—a judge who determines whether or not a soul is worthy of reincarnation. To aid in his judgment, the bar’s patrons are forced to play simple games laced with sadistic twists designed to bring their true natures to light. To Decim, judgment has always been black and white—that is—until he meets a mysterious young woman whose fate seems impossible to decide. His indecision shakes the very foundation of the games and raises the biggest question of all: Who is fit to judge the dead? (Source: Funimation)', 80, 474325, 12, 'FINISHED', 'TV'),
    (108465, '{"romaji":"Mushoku Tensei: Isekai Ittara Honki Dasu","english":"Mushoku Tensei: Jobless Reincarnation","native":"無職転生 ～異世界行ったら本気だす～","userPreferred":"Mushoku Tensei: Isekai Ittara Honki Dasu"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx108465-1ANspF1EWyFx.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108465-1ANspF1EWyFx.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108465-RgsRpTMhP9Sv.jpg', 'When a 34-year-old underachiever gets run over by a bus, his story doesn’t end there. Reincarnated in a new world as an infant, Rudeus will seize every opportunity to live the life he’s always wanted. Armed with new friends, some freshly acquired magical abilities, and the courage to do the things he’s always dreamed of, he’s embarking on an epic adventure—with all of his past experience intact! (Source: Funimation, edited) Note: The anime pre-screened its 1st and 2nd episode starting on the 27th of December on the Nico Nico Live Broadcasting and D Anime Store services', 81, 472069, 11, 'FINISHED', 'TV'),
    (99263, '{"romaji":"Tate no Yuusha no Nariagari","english":"The Rising of the Shield Hero","native":"盾の勇者の成り上がり","userPreferred":"Tate no Yuusha no Nariagari"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx99263-LcazQwdlWzMy.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99263-LcazQwdlWzMy.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99263-IwkmdCTsDY1t.jpg', 'Naofumi Iwatani, an uncharismatic Otaku who spends his days on games and manga, suddenly finds himself summoned to a parallel universe! He discovers he is one of four heroes equipped with legendary weapons and tasked with saving the world from its prophesied destruction. As the Shield Hero, the weakest of the heroes, all is not as it seems. Naofumi is soon alone, penniless, and betrayed. With no one to turn to, and nowhere to run, he is left with only his shield. Now, Naofumi must rise to become the legendary Shield Hero and save the world! Note: - The first episode was pre-aired on December 27th, 2018. Regular broadcast began on January 9th, 2019. - The first episode aired with a runtime of ~47 minutes as opposed to the standard 24 minute long episode.', 76, 469964, 25, 'FINISHED', 'TV'),
    (9919, '{"romaji":"Ao no Exorcist","english":"Blue Exorcist","native":"青の祓魔師","userPreferred":"Ao no Exorcist"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx9919-nXS7JOZrWHfS.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9919-nXS7JOZrWHfS.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9919-S5idQm3GbZ80.jpg', 'This world consists of two dimensions joined as one, like a mirror. The first is the world in which the humans live, Assiah. The other is the world of demons, Gehenna. Ordinarily, travel between the two, and indeed any kind of contact between the two, is impossible. However the demons can pass over into this world by possessing anything that exist within it. Satan the god of demons, but there''s one thing that he doesn''t have, and that''s a substance in the human world that is powerful enough to contain him!! For that purpose he created Rin, his son from a human woman, but will his son agree to his plans? Or will he become something else...? An exorcist?', 72, 467914, 25, 'FINISHED', 'TV'),
    (98314, '{"romaji":"Kakegurui","english":"Kakegurui","native":"賭ケグルイ","userPreferred":"Kakegurui"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b98314-TSJykxVwCCQN.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b98314-TSJykxVwCCQN.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98314-gwgiHiJOj2ls.jpg', 'During daylight hours, an exclusive, elite private school prepares its illustrious students for careers in business, politics, and high society. But when darkness falls, the halls of this esteemed establishment transform into an underground gambling den where bright-eyed youngsters learn the timeless art of bluffing, backdoor dealings and social manipulation. In this school for the rich and elite, money is power, and the tyrant of the betting books rules with an iron fist. So when the beautiful Yumeko Jabami upsets the academy hierarchy with her voracious appetite for the thrill of the gamble, the entire student body mobilizes to send her house of cards tumbling down. (Source: Sentai Filmworks)', 70, 462909, 12, 'FINISHED', 'TV'),
    (151807, '{"romaji":"Ore dake Level Up na Ken","english":"Solo Leveling","native":"俺だけレベルアップな件","userPreferred":"Ore dake Level Up na Ken"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx151807-it355ZgzquUd.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx151807-it355ZgzquUd.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/151807-37yfQA3ym8PA.jpg', 'They say whatever doesn’t kill you makes you stronger, but that’s not the case for the world’s weakest hunter Seong Jin-U. After being brutally slaughtered by monsters in a high-ranking dungeon, Jin-U came back with the System, a program only he could see, that’s leveling him up in every way. Now, he’s inspired to discover the secrets behind his powers and the dungeon that spawned them. (Source: Crunchyroll)', 80, 462529, 12, 'FINISHED', 'TV'),
    (20594, '{"romaji":"Sword Art Online II","english":"Sword Art Online II","native":"ソードアート・オンライン II","userPreferred":"Sword Art Online II"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/nx20594-FhRgZ1H9Istt.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/nx20594-FhRgZ1H9Istt.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20594-BZOLwqidcS1G.jpg', 'One year after the SAO incident, Kirito is approached by Seijiro Kikuoka from Japan''s Ministry of Internal Affairs and Communications Department "VR Division" with a rather peculiar request. That was an investigation on the "Death Gun" incident that occurred in the gun and steel filled VRMMO called Gun Gale Online (GGO). "Players who are shot by a mysterious avatar with a jet black gun lose their lives even in the real world..." Failing to turn down Kikuoka''s bizarre request, Kirito logs in to GGO even though he is not completely convinced that the virtual world could physically affect the real world. Kirito wanders in an unfamiliar world in order to gain any clues about the "Death Gun." Then, a female sniper named Sinon who owns a gigantic "Hecate II" rifle extends Kirito a helping hand. With Sinon''s help, Kirito decides to enter the "Bullet of Bullets," a large tournament to choose the most powerful gunner within the realm of GGO, in hopes to become the target of the "Death Gun" and make direct contact with the mysterious avatar. (Source: Crunchyroll)', 65, 459100, 24, 'FINISHED', 'TV'),
    (98659, '{"romaji":"Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e","english":"Classroom of the Elite","native":"ようこそ実力至上主義の教室へ","userPreferred":"Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx98659-WNyPLIZDpGGY.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx98659-WNyPLIZDpGGY.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98659-u46B5RCNl9il.jpg', 'Koudo Ikusei Senior High School is a leading school with state-of-the-art facilities. The students there have the freedom to wear any hairstyle and bring any personal effects they desire. Koudo Ikusei is like a utopia, but the truth is that only the most superior students receive favorable treatment. Kiyotaka Ayanokouji is a student of D-class, which is where the school dumps its "inferior" students in order to ridicule them. For a certain reason, Kiyotaka was careless on his entrance examination, and was put in D-class. After meeting Suzune Horikita and Kikyou Kushida, two other students in his class, Kiyotaka''s situation begins to change. (Source: Anime News Network, edited)', 76, 457640, 12, 'FINISHED', 'TV'),
    (101338, '{"romaji":"Mob Psycho 100 II","english":"Mob Psycho 100 II","native":"モブサイコ100 II","userPreferred":"Mob Psycho 100 II"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx101338-rokVscjRYzdP.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101338-rokVscjRYzdP.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101338-Rl54Qhx71dUq.jpg', 'Kageyama is an ordinary 8th grader who just wants to live a normal life. Although he can disappear in the crowd in a flash, he was actually the most powerful psychic. The lives of those around Mob and his numerous feelings that softly piles up for the eventual explosion. The mysterious group "Claw" stands before him once again. In the midst of his youthful days, where will his roaring heart take him!? (Source: Crunchyroll)', 87, 457156, 13, 'FINISHED', 'TV'),
    (120120, '{"romaji":"Tokyo Revengers","english":"Tokyo Revengers","native":"東京リベンジャーズ","userPreferred":"Tokyo Revengers"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx120120-cWDmnmeEntSe.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx120120-cWDmnmeEntSe.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/120120-UDYgoHA69peT.jpg', 'Takemichi Hanagaki is a freelancer that''s reached the absolute pits of despair in his life. He finds out that the only girlfriend he ever had in his life that he dated in middle school, Hinata Tachibana, had been killed by the ruthless Tokyo Manji Gang. The day after hearing about her death, he''s standing on the station platform and ends up being pushed over onto the tracks by a herd of people. He closes his eyes thinking he''s about to die, but when he opens his eyes back up, he somehow had gone back in time 12 years. Now that he''s back living the best days of his life, Takemichi decides to get revenge on his life by saving his girlfriend and changing himself that he''d been running away from. (Source: Crunchyroll)', 77, 454848, 24, 'FINISHED', 'TV'),
    (131681, '{"romaji":"Shingeki no Kyojin: The Final Season Part 2","english":"Attack on Titan Final Season Part 2","native":"進撃の巨人 The Final Season Part 2","userPreferred":"Shingeki no Kyojin: The Final Season Part 2"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx131681-5ooUqvqNtee1.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131681-5ooUqvqNtee1.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/131681-3tNurPRsqsfz.jpg', 'The war for Paradis zeroes in on Shiganshina just as Jaegerists have seized control. After taking a huge blow from a surprise attack led by Eren, Marley swiftly acts to return the favor. With Zeke’s true plan revealed and a military forced under new rule, this battle might be fought on two fronts. Does Eren intend on fulfilling his half-brother’s wishes or does he have a plan of his own? (Source: Funimation)', 87, 452254, 12, 'FINISHED', 'TV'),
    (6547, '{"romaji":"Angel Beats!","english":"Angel Beats!","native":"Angel Beats!","userPreferred":"Angel Beats!"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx6547-SYexAn5aFyss.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx6547-SYexAn5aFyss.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/6547-YUUiSjKyxxeQ.jpg', 'Otonashi wakes up in the afterlife to find out he has no memories of his life before death. Desperate to survive in a war that could yield another unfortunate fate, he joins the SSS in the battle against Angel, whose very mission is to destroy all inhabitants of this afterlife. As Otonashi struggles to recover his memory and learn more about this world, he finds that not all is as it had seemed. (Source: Funimation)', 77, 450084, 13, 'FINISHED', 'TV'),
    (131573, '{"romaji":"Jujutsu Kaisen 0","english":"JUJUTSU KAISEN 0","native":"呪術廻戦 0","userPreferred":"Jujutsu Kaisen 0"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx131573-rpl82vDEDRm6.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx131573-rpl82vDEDRm6.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/131573-3veuVz5p0z2I.jpg', 'Yuta Okkotsu is a nervous high school student who is suffering from a serious problem—his childhood friend Rika has turned into a curse and won''t leave him alone. Since Rika is no ordinary curse, his plight is noticed by Satoru Gojo, a teacher at Jujutsu High, a school where fledgling exorcists learn how to combat curses. Gojo convinces Yuta to enroll, but can he learn enough in time to confront the curse that haunts him? (Source: VIZ Media)', 83, 448455, 1, 'FINISHED', 'MOVIE'),
    (132405, '{"romaji":"Sono Bisque Doll wa Koi wo Suru","english":"My Dress-Up Darling","native":"その着せ替え人形は恋をする","userPreferred":"Sono Bisque Doll wa Koi wo Suru"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx132405-qP7FQYGmNI3d.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx132405-qP7FQYGmNI3d.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/132405-LnPQaqaksEpN.jpg', 'High schooler Wakana Gojou cares about one thing: making Hina dolls. With nobody to share his obsession, he has trouble finding friends—or even holding conversation. But after the school’s most popular girl, Marin Kitagawa, reveals a secret of her own, he discovers a new purpose for his sewing skills. Together, they’ll make her cosplay dreams come true! (Source: Funimation)', 80, 442961, 12, 'FINISHED', 'TV'),
    (112641, '{"romaji":"Kaguya-sama wa Kokurasetai?: Tensaitachi no Renai Zunousen","english":"Kaguya-sama: Love is War?","native":"かぐや様は告らせたい？～天才たちの恋愛頭脳戦～","userPreferred":"Kaguya-sama wa Kokurasetai?: Tensaitachi no Renai Zunousen"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx112641-zoGC8d6FaPXU.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx112641-zoGC8d6FaPXU.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112641-mKZe0zng0ndV.jpg', 'After a slow but eventful summer vacation, Shuchiin Academy''s second term is now starting in full force. As August transitions into September, Miyuki Shirogane''s birthday looms ever closer, leaving Kaguya Shinomiya in a serious predicament as to how to celebrate it. Furthermore, the tenure of the school''s 67th student council is coming to an end. Due to the council members being in different classes, the only time Kaguya and Miyuki have to be together will soon disappear, putting all of their cunning plans at risk. A long and difficult election that will decide the fate of the new student council awaits, as multiple challengers fight for the coveted title of president. (Source: MAL Rewrite)', 85, 442226, 12, 'FINISHED', 'TV'),
    (20997, '{"romaji":"Charlotte","native":"Charlotte(シャーロット)","userPreferred":"Charlotte"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20997-axVYrsIfjtYJ.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20997-axVYrsIfjtYJ.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20997-nE9VyUa08vS0.jpg', 'Very few adolescent boys and girls develop special abilities. Yuu Otosaka is one such man who uses his ability, unbeknownst to others, in order to lead a satisfying school life. Then one day, a girl named Nao Tomori suddenly appears before him. Their encounter reveals the destiny for wielders of special abilities. This is a story of those gifted youth and how they spend their adolescence. (Source: Crunchyroll)', 75, 442117, 13, 'FINISHED', 'TV'),
    (10620, '{"romaji":"Mirai Nikki","english":"The Future Diary","native":"未来日記","userPreferred":"Mirai Nikki"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx10620-dUZeNej0W4QN.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx10620-dUZeNej0W4QN.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10620-CsZ2FFSbGpqV.jpg', 'This psychological thriller, based on the manga written and illustrated by Sakae Esuno, is about Yuki, a loner who''s not very good with people. He prefers to write a diary on his cell phone and talk to his imaginary friend, Deus Ex Machina – The God of Time and Space. However, Yuki soon learns that Deus is more than a figment of his imagination when he makes Yuki participate in a battle royale with eleven others. The contestants are given special diaries that can predict the future, each diary possessing unique features that give it both advantages and disadvantages. Within the next 90 days, the contestants must try to survive until there is only one left standing. The winner will become the new God of Time and Space. (Source: FUNimation)', 69, 438070, 26, 'FINISHED', 'TV'),
    (21311, '{"romaji":"Bungou Stray Dogs","english":"Bungo Stray Dogs","native":"文豪ストレイドッグス","userPreferred":"Bungou Stray Dogs"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21311-hAXyT8Yoh6G9.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21311-hAXyT8Yoh6G9.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21311-oVJYXoU38Lm5.jpg', 'Stalked by a beastly white tiger, Atsushi Nakajima has no idea that the menace lives inside him—a power that catches the attention of the Armed Detective Agency. Using inhuman abilities to combat crime, this team takes Atsushi under the wing of their most eccentric member, Dazai. Together, they tear through mafia-muddled mysteries while enemies keep an eye on the tiger’s lofty bounty. (Source: Funimation)', 77, 427998, 12, 'FINISHED', 'TV'),
    (117193, '{"romaji":"Boku no Hero Academia 5","english":"My Hero Academia Season 5","native":"僕のヒーローアカデミア５","userPreferred":"Boku no Hero Academia 5"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx117193-E75BlZmDh1aB.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx117193-E75BlZmDh1aB.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/117193-37OySoeOMN0z.jpg', 'The rivalry between Class 1-A and Class 1-B heats up in a joint training battle. Eager to be a part of the hero course, brainwashing buff Shinso is tasked with competing on both sides. But as each team faces their own weaknesses and discovers new strengths, this showdown might just become a toss-up. (Source: Funimation)', 73, 422804, 25, 'FINISHED', 'TV'),
    (18679, '{"romaji":"Kill la Kill","english":"Kill la Kill","native":"キルラキル","userPreferred":"Kill la Kill"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b18679-lbkq7iYESoFW.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b18679-lbkq7iYESoFW.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/18679-rpC99hxBxaMn.jpg', 'After the murder of her father, Ryuuko Matoi has been wandering the land in search of his killer. Following her only lead—the missing half of his invention, the Scissor Blade—she arrives at the prestigious Honnouji Academy, a high school unlike any other. The academy is ruled by the imposing and cold-hearted student council president Satsuki Kiryuuin alongside her powerful underlings, the Elite Four. In the school''s brutally competitive hierarchy, Satsuki bestows upon those at the top special clothes called "Goku Uniforms," which grant the wearer unique superhuman abilities.', 79, 421363, 24, 'FINISHED', 'TV'),
    (20850, '{"romaji":"Tokyo Ghoul √A","english":"Tokyo Ghoul √A","native":"東京喰種[トーキョーグール]√A","userPreferred":"Tokyo Ghoul √A"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20850-glDf9EMKeCwe.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20850-glDf9EMKeCwe.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20850-YjtRXQkNl0xz.jpg', 'The ghouls of Anteiku invaded the Aogiri''s site in order to rescue Ken Kaneki who is being tortured. Due to provocation, he unleashed greater power enough to defeat Yamori. To become stronger, he decided to join Aogiri and left Anteiku. Ghoul investigators also making their moves by collecting information about the eye-patched ghoul - Ken Kaneki. (Source: Anime News Network)', 67, 413868, 12, 'FINISHED', 'TV'),
    (20832, '{"romaji":"Overlord","english":"Overlord","native":"オーバーロード","userPreferred":"Overlord"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20832-vUNm5zrYWifc.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20832-vUNm5zrYWifc.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20832-NswCiSYMoI2k.jpg', 'The story takes place in the year 2138 when virtual reality gaming is booming. Yggdrasil, a popular online game is quietly shut down one day. However, the protagonist Momonga decides to not log out. Momonga is then transformed into the image of a skeleton as "the most powerful wizard." The world continues to change, with non-player characters (NPCs) beginning to feel emotion. Having no parents, friends, or place in society, this ordinary young man Momonga then strives to take over the new world the game has become. (Source: Anime News Network)', 76, 413515, 13, 'FINISHED', 'TV'),
    (97986, '{"romaji":"Made in Abyss","english":"Made in Abyss","native":"メイドインアビス","userPreferred":"Made in Abyss"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx97986-TQ7dCgbS3y5s.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx97986-TQ7dCgbS3y5s.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97986-C55UnbJKB7ZF.jpg', 'The "Abyss" is the last unexplored place in the world. Strange and wonderful creatures roam within, and it is full of precious relics that present humans can''t recreate. Those that dare to explore the depths are known as "Cave Raiders." An orphan girl named Riko lives on the rim. Her dream is to become a Cave Raider like her mother and solve the mysteries of the cave system. One day, Riko starts exploring the caves and discovers a robot who resembles a human boy. (Source: Anime News Network, edited) Note: The last episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.', 84, 413341, 13, 'FINISHED', 'TV'),
    (120377, '{"romaji":"Cyberpunk: Edgerunners","english":"Cyberpunk: Edgerunners","native":"サイバーパンク エッジランナーズ","userPreferred":"Cyberpunk: Edgerunners"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx120377-ayZPoxiWt4Li.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx120377-ayZPoxiWt4Li.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/120377-c15oLS8CA31s.jpg', 'Cyberpunk: Edgerunners tells a standalone, 10-episode story about a street kid trying to survive in a technology and body modification-obsessed city of the future. Having everything to lose, he chooses to stay alive by becoming an edgerunner—a mercenary outlaw also known as a cyberpunk. (Source: CD PROJEKT RED) Note: The first episode received a pre-screening at Anime Expo on July 2, 2022. The first 3 dubbed episodes were streamed on Twitch as part of a co-stream promotion on September 12, a day before the show’s premiere.', 85, 410429, 10, 'FINISHED', 'ONA'),
    (20923, '{"romaji":"Shokugeki no Souma","english":"Food Wars!","native":"食戟のソーマ","userPreferred":"Shokugeki no Souma"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20923-pNT38pjW3RFH.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20923-pNT38pjW3RFH.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20923-9tFdZ5hIrRiF.png', 'Ever since he was little, Souma Yukihira’s main goals have been to beat his father in a cooking contest and take over the family diner. That’s why, when his dad suddenly announces that he’s shutting the restaurant down and sending Souma to cooking school, Souma is shocked. However, Totsuki Academy is no ordinary cooking school. This elite institution is filled with culinary giants like Erina “God Tongue” Nakiri, who does her best to keep a lowly short-order like Souma from even making it inside the door. However, if the snobs can dish it out, Souma can serve it up, and when he learns that only a handful of the students manage to graduate every year, he swears that the only way he’ll leave is as number one! (Source: Sentai Filmworks)', 78, 408950, 24, 'FINISHED', 'TV'),
    (20992, '{"romaji":"Haikyuu!! 2nd Season","english":"HAIKYU!! 2nd Season","native":"ハイキュー!! セカンドシーズン","userPreferred":"Haikyuu!! 2nd Season"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20992-aHgNbcalVEqk.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20992-aHgNbcalVEqk.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20992-QMdqxEjAIAit.jpg', 'Following their participation at the Inter-High, the Karasuno High School volleyball team attempts to refocus their efforts, aiming to conquer the Spring tournament instead. When they receive an invitation from long-standing rival Nekoma High, Karasuno agrees to take part in a large training camp alongside many notable volleyball teams in Tokyo and even some national level players. By playing with some of the toughest teams in Japan, they hope not only to sharpen their skills, but also come up with new attacks that would strengthen them. Moreover, Hinata and Kageyama attempt to devise a more powerful weapon, one that could possibly break the sturdiest of blocks. Facing what may be their last chance at victory before the senior players graduate, the members of Karasuno''s volleyball team must learn to settle their differences and train harder than ever if they hope to overcome formidable opponents old and new—including their archrival Aoba Jousai and its world-class setter Tooru Oikawa. [Written by MAL Rewrite]', 86, 405108, 25, 'FINISHED', 'TV'),
    (20920, '{"romaji":"Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka","english":"Is It Wrong to Try to Pick Up Girls in a Dungeon?","native":"ダンジョンに出会いを求めるのは間違っているだろうか","userPreferred":"Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx20920-MTREwZOG4BAD.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx20920-MTREwZOG4BAD.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20920-QZeO1gVTQSUZ.jpg', 'Some adventurers delve into the sprawling labyrinths beneath the city of Orario to find fame and fortune. Others come to test their skills against the legions of monsters lurking in the darkness below. However, Bell Cranel’s grandfather told him a different reason: it’s a great place to rescue (and subsequently meet) girls! Now that Bell’s a dungeon delver himself, the ladies he’s encountering aren’t the helpless damsels in distress he’d imagined, and one of them, the beautiful swordswoman Ais Wallenstein, keeps rescuing Bell instead. As embarrassing as that is, it’s nothing compared to what happens when goddesses get involved. Freya, Hephaistos, and Loki, with their powerful Familias, are intimidating enough, but there’s one goddess whose relationship with Bell is certain to spark trouble. (Source: Sentai Filmworks)', 73, 404070, 13, 'FINISHED', 'TV'),
    (3588, '{"romaji":"Soul Eater","english":"Soul Eater","native":"ソウルイーター","userPreferred":"Soul Eater"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx3588-fSMggQoFSbUI.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx3588-fSMggQoFSbUI.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/3588-rpnVOMaLD3is.jpg', 'Set in the Shinigami technical school for weapon meisters, the series revolves around 3 groups of each a weapon meister and a human weapon. Trying to make the latter a "Death Scythe" which is the highest title for a weapon and thus fit for use by the Shinigami, they must collect the souls of 99 evil humans and 1 witch. Maka & Soul Eater, Black Star & Tsubaki, and Death the Kid with Patty and Liz Thompson are the characters Soul Eater revolves around. Besides taking the time to gather souls, these students of Shibusen defend Death City from some of the most powerful of creatures while still attending school and trying to become stronger.', 77, 401993, 51, 'FINISHED', 'TV'),
    (15809, '{"romaji":"Hataraku Maou-sama!","english":"The Devil is a Part-Timer!","native":"はたらく魔王さま!","userPreferred":"Hataraku Maou-sama!"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx15809-ECv3HyOYJKrk.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx15809-ECv3HyOYJKrk.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/15809-kX2mopBGBw6g.jpg', 'Devil King Sadao is only one step away from conquering the world when he is beaten by Hero Emilia and forced to drift to the other world: modern-day Tokyo. As "conquering the world" are the only skills the Devil King possesses—and are obviously unnecessary in his new situation—he must work as a freeter to pay for his living expenses!', 75, 401923, 13, 'FINISHED', 'TV'),
    (9989, '{"romaji":"Ano Hi Mita Hana no Namae wo Bokutachi wa Mada Shiranai.","english":"Anohana: The Flower We Saw That Day","native":"あの日見た花の名前を僕達はまだ知らない。","userPreferred":"Ano Hi Mita Hana no Namae wo Bokutachi wa Mada Shiranai."}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx9989-hImMg6kCMm6I.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx9989-hImMg6kCMm6I.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9989-pyr6rXlV1oAm.jpg', 'Jinta Yadomi and his group of childhood friends have become estranged after a tragic accident split them apart. Now in their high school years, a sudden surprise forces each of them to confront their guilt over what happened that day and come to terms with the ghosts of their past. (Source: NIS America)', 80, 399835, 11, 'FINISHED', 'TV'),
    (171018, '{"romaji":"Dandadan","english":"DAN DA DAN","native":"ダンダダン","userPreferred":"Dandadan"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx171018-60q1B6GK2Ghb.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx171018-60q1B6GK2Ghb.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/171018-SpwPNAduszXl.jpg', 'This is a story about Momo, a high school girl who comes from a family of spirit mediums, and her classmate Okarun, an occult fanatic. After Momo rescues Okarun from being bullied, they begin talking. However, an argument ensues between them since Momo believes in ghosts but denies aliens exist, and Okarun believes in aliens but denies ghosts exist. To prove to each other what they believe in is real, Momo goes to an abandoned hospital where a UFO has been spotted and Okarun goes to a tunnel rumored to be haunted. To their surprise, they each encounter overwhelming paranormal activities that transcend comprehension. Amid these predicaments, Momo awakens her hidden power and Okarun gains the power of a curse to overcome these new dangers! Their fateful love begins as well!? The story of the occult battle and adolescence starts! (Source: Crunchyroll) Notes: - Worldwide premiere of Episode 1 before the Japanese television premiere occurred at Anime Expo July 6, 2024. - Episodes 1-3 titled as DAN DA DAN: FIRST ENCOUNTER was pre-screened in advance in theaters on August 31, 2024 in Asia, September 7, 2024 in Europe and September 13, 2024 in North America. The regular TV broadcast began ', 83, 398943, 12, 'FINISHED', 'TV'),
    (11111, '{"romaji":"Another","english":"Another","native":"アナザー","userPreferred":"Another"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx11111-gvvE5bBYsyFo.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx11111-gvvE5bBYsyFo.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11111.jpg', 'When Kouichi Sakakibara transfers to a new school, he senses a frightening atmosphere in his new class, a secret none of them will talk about. At the center is the beautiful Mei Misaki. Kouichi is immediately drawn to her mysterious aura, but he begins to realize that no one else in the class is aware of her presence. Soon after his arrival, what is known as the Calamity begins, and it claims the lives of many students. (Source: Sentai Filmworks)', 71, 391863, 12, 'FINISHED', 'TV'),
    (108632, '{"romaji":"Re:Zero kara Hajimeru Isekai Seikatsu 2nd Season","english":"Re:ZERO -Starting Life in Another World- Season 2","native":"Re:ゼロから始める異世界生活 2nd Season","userPreferred":"Re:Zero kara Hajimeru Isekai Seikatsu 2nd Season"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx108632-lQWnmw7XaNOK.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx108632-lQWnmw7XaNOK.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108632-yeLbrgPN4Oni.jpg', 'Even after dying countless times, Subaru finally ended the threat of the White Whale and defeated the Witch Cult''s Sin Archbishop representing sloth, Petelgeuse Romaneeconti. But only shortly after overcoming a tragic ending and reuniting with his beloved Emilia, Subaru learns that Rem has been erased from this world, having fallen victim to the White Whale''s Fog of Elimination in the midst of Subaru''s death loop. With the White Whale now gone, Subaru and Emilia are forced to confront a reality they never dreamed would happen. (Source: Crunchyroll)', 83, 390476, 13, 'FINISHED', 'TV'),
    (14813, '{"romaji":"Yahari Ore no Seishun Love Come wa Machigatteiru.","english":"My Teen Romantic Comedy SNAFU","native":"やはり俺の青春ラブコメはまちがっている。","userPreferred":"Yahari Ore no Seishun Love Come wa Machigatteiru."}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx14813-3mNvcKNEQcDs.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx14813-3mNvcKNEQcDs.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/14813-urImBxyWJUEw.jpg', 'This romantic comedy revolves around an antisocial high school student named Hikigaya Hachiman with a distorted view on life and no friends or girlfriend. When he sees his classmates talking excitedly about living their adolescent lives, he mutters: "They''re a bunch of liars." When he is asked about his future dreams, he responds: "Not working." A teacher gets Hachiman to join the ''Volunteer Service'' club, which happens to have the school''s prettiest girl: Yukinoshita Yukino. (Source: Anime News Network)', 78, 390159, 13, 'FINISHED', 'TV'),
    (2001, '{"romaji":"Tengen Toppa Gurren Lagann","english":"Gurren Lagann","native":"天元突破グレンラガン","userPreferred":"Tengen Toppa Gurren Lagann"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx2001-XwRnjzGeFWRQ.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx2001-XwRnjzGeFWRQ.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/2001-3eWhvkau8NV3.jpg', 'In a far away future, mankind lives underground in huge caves, unknowing of a world above with a sky and stars. In the small village of Jiha, Simon, a shy boy who works as a digger discovers a strange glowing object during excavation. The enterprising Kamina, a young man with a pair of rakish sunglasses and the passion of a firey sun, befriends Simon and forms a small band of brothers, the Gurren Brigade, to escape the village and break through the ceiling of the cave to reach the surface, which few believe exist. The village elder won''t hear of such foolishness and punishes the Brigade. However, when disaster strikes from the world above and the entire village is in jeopardy, it''s up to Simon, Kamina, a girl with a big gun named Yoko, and the small yet sturdy robot, Lagann, to save the day. The new friends journey to the world above and find that the surface is a harsh battlefield, and it''s up to them to fight back against the rampaging Beastmen to turn the tide in the humans'' favor! Pierce the heavens, Gurren Lagann!', 85, 389125, 27, 'FINISHED', 'TV'),
    (6702, '{"romaji":"FAIRY TAIL","english":"Fairy Tail","native":"FAIRY TAIL","userPreferred":"FAIRY TAIL"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b6702-KI4qgSMyI8Pm.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/b6702-KI4qgSMyI8Pm.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/6702-VSHyctSAeUBS.jpg', 'Across the Fiore kingdom, wizards join guilds and make their pay by filling magical needs—but one guild has a reputation as the roughest, rowdiest, most dangerous of all: Fairy Tail! When four young Fairy Tail members unite, their bond is forged by a power found in neither muscle nor magic and grows stronger with every mission. Whatever you do, don''t mess with these friends or you''ll get a taste of Natsu''s flaming fist or Gray''s ice hammer, suffer a painful blow from one of Lucy''s celestial spirits or catch the edge of Erza''s mighty blade! Whether they''re stopping demons from devastating the world or wrestling in the mess hall, this mystical team manages to inflict as much damage to their rivals as they do to the surrounding area! (Source: Funimation)', 72, 386897, 175, 'FINISHED', 'TV'),
    (99750, '{"romaji":"Kimi no Suizou wo Tabetai","english":"I Want to Eat Your Pancreas","native":"君の膵臓をたべたい","userPreferred":"Kimi no Suizou wo Tabetai"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx99750-pNyly9d3MEgV.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx99750-pNyly9d3MEgV.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99750-KPFW2Jv03b2B.jpg', 'Spring time in April and the last of the cherry blossoms are still in bloom. The usually aloof bookworm with no interest in others comes across a book in a hospital waiting room. Handwritten on the cover are the words: "Living with Dying." He soon discovers that it is a diary kept by his very popular and genuinely cheerful classmate, Sakura Yamauchi, who reveals to him that she is secretly suffering from a pancreatic illness and only has a limited time left. It is at this moment that she gains just one more person to share her secret. Trying to maintain a normal life as much as possible, Sakura is determined to live her life to the fullest until the very last day. As her free spirit and unpredictable actions throw him for a loop, his heart begins to gradually change. (Source: Aniplex USA)', 84, 383880, 1, 'FINISHED', 'MOVIE'),
    (21699, '{"romaji":"Kono Subarashii Sekai ni Shukufuku wo! 2","english":"KONOSUBA -God''s blessing on this wonderful world! 2","native":"この素晴らしい世界に祝福を！2","userPreferred":"Kono Subarashii Sekai ni Shukufuku wo! 2"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx21699-Fkbnkl9ZC6fW.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx21699-Fkbnkl9ZC6fW.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21699-1PwL1P4i61wP.jpg', 'When Kazuma Satou died, he was given two choices: pass on to heaven or be revived in a fantasy world. After choosing the new world, the goddess Aqua tasked him with defeating the Demon King, and let him choose any weapon to aid him. Unfortunately, Kazuma chose to bring Aqua herself and has regretted the decision ever since then. Not only is he stuck with a useless deity turned party archpriest, the pair also has to make enough money for living expenses. To add to their problems, their group continued to grow as more problematic adventurers joined their ranks. Their token spellcaster, Megumin, is an explosion magic specialist who can only cast one spell once per day and refuses to learn anything else. There is also their stalwart crusader, Lalatina "Darkness" Dustiness Ford, a helpless masochist who makes Kazuma look pure in comparison. Kono Subarashii Sekai ni Shukufuku wo! 2 continues to follow Kazuma and the rest of his party through countless more adventures as they struggle to earn money and have to deal with one another''s problematic personalities. However, things rarely go as planned, and they are often sidetracked by their own idiotic tendencies.', 80, 383565, 10, 'FINISHED', 'TV'),
    (145139, '{"romaji":"Kimetsu no Yaiba: Katanakaji no Sato-hen","english":"Demon Slayer: Kimetsu no Yaiba Swordsmith Village Arc","native":"鬼滅の刃 刀鍛冶の里編","userPreferred":"Kimetsu no Yaiba: Katanakaji no Sato-hen"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx145139-rRimpHGWLhym.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx145139-rRimpHGWLhym.png"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/145139-V01Prh6UzfRk.jpg', 'Tanjiro’s journey leads him to the Swordsmith Village, where he reunites with two Hashira, members of the Demon Slayer Corps’ highest-ranking swordsmen - Mist Hashira Muichiro Tokito and Love Hashira Mitsuri Kanroji. With the shadows of demons lurking near, a new battle begins for Tanjiro and his comrades. Notes: • The first episode has a runtime of ~49 minutes, and received an early premiere in cinemas worldwide as part of a special screening alongside the final two episodes of Kimetsu no Yaiba: Yuukaku-hen. • The final episode has a runtime of ~52 minutes.', 80, 383471, 11, 'FINISHED', 'TV'),
    (101347, '{"romaji":"Dororo","english":"Dororo","native":"どろろ","userPreferred":"Dororo"}'::jsonb, '{"large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx101347-TGaDwEYqLfm1.jpg","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx101347-TGaDwEYqLfm1.jpg"}'::jsonb, 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n101347-tHurKfTlhtFl.jpg', 'Dororo, a young orphan thief, meets Hyakkimaru, a powerful ronin. Hyakkimaru''s father, a greedy feudal lord, had made a pact with 12 demons, offering his yet-unborn son''s body parts in exchange for great power. Thus, Hyakkimaru - who was born without arms, legs, eyes, ears, a nose or a mouth - was abandoned in a river as a baby. Rescued and raised by Dr. Honma, who equips him with artificial limbs and teaches him sword-fighting techniques, Hyakkimaru discovers that each time he slays a demon, a piece of his body is restored. Now, he roams the war-torn countryside in search of demons.', 81, 381800, 24, 'FINISHED', 'TV')
