-- AniWatchlist anime catalog seed from the AniList GraphQL API.
-- Snapshot of the 100 most popular non-adult anime; trending ranks are ordered by AniList trending within this catalog.
-- Refresh this snapshot periodically to keep scores, popularity, and rankings current.

BEGIN;

ON CONFLICT (name) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, cover_image = EXCLUDED.cover_image,
    banner_image = EXCLUDED.banner_image, description = EXCLUDED.description,
    average_score = EXCLUDED.average_score, popularity = EXCLUDED.popularity,
    episodes = EXCLUDED.episodes, status = EXCLUDED.status, format = EXCLUDED.format,
    source_updated_at = now(), updated_at = now();

DELETE FROM anime_genres WHERE anime_id IN (16498, 101922, 113415, 1535, 21459, 11061, 21087, 21, 20605, 20958, 5114, 20, 20954, 11757, 21519, 99147, 21856, 110277, 127230, 101759, 20755, 21507, 21355, 20665, 104578, 1735, 21234, 100166, 9253, 97940, 20464, 101291, 140960, 101921, 105333, 101348, 21827, 124080, 4224, 19815, 20613, 20447, 104276, 20789, 269, 21202, 112151, 1575, 99423, 20623, 145064, 30, 154587, 142329, 105310, 199, 14719, 1, 97668, 101280, 20931, 108465, 99263, 9919, 98314, 151807, 20594, 98659, 101338, 120120, 131681, 6547, 131573, 132405, 112641, 20997, 10620, 21311, 117193, 18679, 20850, 20832, 97986, 120377, 20923, 20992, 20920, 3588, 15809, 9989, 171018, 11111, 108632, 14813, 2001, 6702, 99750, 21699, 145139, 101347);


DELETE FROM anime_lists WHERE list IN ('trending', 'popular');

COMMIT;
